/* Approved: random clockwise stars; braided river in right gutter only. */
(()=>{'use strict';
const assets={"dbs":"data:image/webp;base64,","china":"data:image/webp;base64,","medical":"data:image/webp;base64,","fugui":"data:image/webp;base64,","deyu":"data:image/webp;base64,"};
const style=document.createElement('style');style.textContent=`
.event-body{position:relative;isolation:isolate;overflow:hidden}
.event-body>.event-title,.event-body>.note,.event-body>.state{position:relative;z-index:2}
.crm-watermark{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;object-position:82% center;opacity:.32;pointer-events:none;z-index:0;mask-image:linear-gradient(90deg,transparent,black 42%)}
.event-body::after{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(90deg,var(--identity-tint),transparent 82%);opacity:.64}
.entry[data-cat=seed]{--identity-tint:#fff0ee}.entry[data-cat=dbs]{--identity-tint:#eee4f8}.entry[data-cat=china]{--identity-tint:#f8e3e1}.entry[data-cat=medical]{--identity-tint:#dff1f0}.entry[data-cat=fugui]{--identity-tint:#e2eafa}.entry[data-cat=deyu]{--identity-tint:#e2efdf}
.entry[data-cat=medical] .crm-watermark{inset:auto 0 auto auto;mask-image:none}
.crm-star-field{position:absolute;inset:0;width:100%;height:100%;opacity:.78;z-index:0;pointer-events:none;mask-image:linear-gradient(90deg,transparent,black 48%)}
#crm-river{position:fixed;pointer-events:none;z-index:0;contain:strict}
@media(max-width:680px){.crm-watermark{mask-image:none;object-position:center}.crm-star-field{mask-image:none;opacity:.58}}
`;document.head.append(style);
const river=document.createElement('canvas');river.id='crm-river';river.setAttribute('aria-hidden','true');document.body.append(river);
const rc=river.getContext('2d'),mq=matchMedia('(prefers-reduced-motion:reduce)'),tau=Math.PI*2;
let items=[],raf=0,time=0,last=0,rw=0,rh=0,dirty=true;
const frac=x=>x-Math.floor(x),random=(n,s)=>frac(Math.sin(n*127.1+s)*43758.5453);
const enabled=()=>!document.hidden&&!mq.matches&&document.documentElement.dataset.motion!=='off';
function star(c,x,y,r,a,g,alpha){c.save();c.translate(x,y);c.rotate(a);c.globalAlpha=alpha;c.fillStyle=g;c.beginPath();c.moveTo(0,-r);c.quadraticCurveTo(r*.12,-r*.12,r,0);c.quadraticCurveTo(r*.12,r*.12,0,r);c.quadraticCurveTo(-r*.12,r*.12,-r,0);c.quadraticCurveTo(-r*.12,-r*.12,0,-r);c.fill();c.restore();}
const visibility=new IntersectionObserver(es=>{for(const e of es){const item=items.find(i=>i.card===e.target);if(item)item.visible=e.isIntersecting;}wake();});
function scan(){items.forEach(i=>i.ro.disconnect());visibility.disconnect();items=[];
document.querySelectorAll('#months .entry[data-cat]').forEach(entry=>{const card=entry.querySelector('.event-body'),cat=entry.dataset.cat;if(!card)return;
card.querySelectorAll('.crm-watermark,.crm-star-field').forEach(x=>x.remove());
if(assets[cat]){const img=new Image();img.className='crm-watermark';img.alt='';img.src=assets[cat];card.prepend(img);if(cat==='medical'){const fit=()=>{const w=card.clientWidth,h=card.clientHeight,iw=Math.min(w*(w<500?.72:.46),h*579/250),ih=iw*869/579;Object.assign(img.style,{width:iw+'px',height:ih+'px',top:(h>=ih?(h-ih)/2:-120*iw/579)+'px'});};const ro=new ResizeObserver(fit);ro.observe(card);items.push({card,ro,type:'image',visible:false});}return;}
if(cat!=='seed')return;const canvas=document.createElement('canvas');canvas.className='crm-star-field';canvas.setAttribute('aria-hidden','true');card.prepend(canvas);
const item={card,canvas,c:canvas.getContext('2d'),type:'star',w:0,h:0,angle:0,power:0,seed:Math.random()*10000,visible:false};
item.ro=new ResizeObserver(()=>{item.w=card.clientWidth;item.h=card.clientHeight;const d=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(item.w*d);canvas.height=Math.round(item.h*d);item.c.setTransform(d,0,0,d,0,0);dirty=true;wake();});item.ro.observe(card);items.push(item);visibility.observe(card);
card.onpointerenter=()=>{item.power=1.5;wake();};card.onclick=()=>{item.power=2.5;wake();};card.tabIndex=0;card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();item.power=2.5;wake();}};
});dirty=true;wake();}
function layout(){const wrap=document.querySelector('.wrap').getBoundingClientRect(),left=Math.ceil(wrap.right+20),available=document.documentElement.clientWidth-left-20;rw=available>=48?Math.min(available,280):0;rh=innerHeight;Object.assign(river.style,{left:left+'px',top:'0px',width:rw+'px',height:rh+'px',display:rw?'block':'none'});const d=Math.min(devicePixelRatio||1,1.5);river.width=Math.round(rw*d);river.height=Math.round(rh*d);rc.setTransform(d,0,0,d,0,0);dirty=true;wake();}
function draw(dt){for(const o of items){if(o.type!=='star'||!o.visible||!o.w||!o.h)continue;const c=o.c,w=o.w,h=o.h,base=Math.min(w,h);c.clearRect(0,0,w,h);o.angle+=dt*(.18+o.power*.65);o.power=Math.max(0,o.power-dt*.8);const g=c.createLinearGradient(w*.5-base*.3,h*.48-base*.3,w*.5+base*.35,h*.48+base*.4);g.addColorStop(0,'#efadc0');g.addColorStop(.45,'#d4789f');g.addColorStop(1,'#a24772');for(let i=0;i<10;i++){const offset=random(i+10,o.seed),life=frac(time*.17+offset),cycle=Math.floor(time*.17+offset),env=Math.sin(life*Math.PI)**2,x=w*(.15+random(i+cycle*19,o.seed)*.7),y=h*(.12+random(i+77+cycle*23,o.seed)*.7);star(c,x,y,base*(.06+random(i+8,o.seed)*.1)*env,o.angle+random(i+17,o.seed)*tau,g,env*.78);if(life>.5){c.globalAlpha=(1-life)*.3;c.strokeStyle='#ba648a';c.beginPath();c.arc(x,y,base*.2*life,0,tau);c.stroke();}}c.globalAlpha=1;}
rc.clearRect(0,0,rw,rh);const block=document.querySelector('#tl-block'),b=block?.getBoundingClientRect();if(!rw||!b||!b.height)return;const top=Math.max(0,b.top),bottom=Math.min(rh,b.bottom),height=bottom-top;if(height<=0)return;const colors=['#de646d','#e4b84d','#4598b8','#76aa99','#ba7cac'];rc.save();rc.beginPath();rc.rect(0,top,rw,height);rc.clip();for(let i=0;i<135;i++){const off=random(i+21,555)*2-1,u=frac(random(i+9,555)+time*(.025+random(i+300,555)*.025)*.4),x=rw*(.5+Math.sin(u*tau*3+time*.1+(off>0?Math.PI:0))*.27+off*.05),y=top+u*height,r=2.5+random(i+91,555)*4;rc.save();rc.translate(x,y);rc.rotate(time*.22+i);rc.globalAlpha=.7*Math.min(1,u*18,(1-u)*18);rc.fillStyle=colors[i%5];rc.strokeStyle=rc.fillStyle;rc.lineWidth=1.3;switch(i%5){case 0:rc.beginPath();rc.arc(0,0,r,0,tau);rc.fill();break;case 1:rc.beginPath();rc.arc(0,0,r,0,tau);rc.stroke();break;case 2:star(rc,0,0,r*1.3,0,rc.fillStyle,rc.globalAlpha);break;case 3:rc.fillRect(-r*1.3,-r*.4,r*2.6,r*.8);break;default:rc.strokeRect(-r*.7,-r*.7,r*1.4,r*1.4);}rc.restore();}rc.restore();}
function frame(now){raf=0;const dt=enabled()?Math.min((now-last)/1000,.06):0;last=now;time+=dt;draw(dt);dirty=false;if(enabled()&&(rw||items.some(i=>i.type==='star'&&i.visible)))raf=requestAnimationFrame(frame);}
function wake(){if(!raf){last=performance.now();raf=requestAnimationFrame(frame);}}
new MutationObserver(scan).observe(document.querySelector('#months'),{childList:true});
new MutationObserver(()=>{dirty=true;wake();}).observe(document.documentElement,{attributes:true,attributeFilter:['data-motion']});
addEventListener('resize',layout);addEventListener('scroll',wake,{passive:true});document.addEventListener('visibilitychange',wake);mq.addEventListener('change',wake);layout();scan();
})();
